-- ============================================================================
-- 073_arith_bd.sql
-- Seed the 'Banker's Discount' Arithmetic chapter of the exam question bank.
-- 37 distinct competitive-exam questions across easy/medium/hard/very_hard,
-- each with 4 options and a worked explanation. Idempotent (skips existing stems).
-- ============================================================================
create or replace function public._seed_arith_q(p_chapter text, p_difficulty text, p_stem text, p_opts text[], p_correct int, p_explanation text) returns void language plpgsql as $fn$
declare v_subj uuid; v_chap uuid; v_qid uuid; i int;
begin
  select id into v_subj from public.subject where lower(name)='arithmetic' limit 1;
  if v_subj is null then raise exception 'Arithmetic subject not found (run 023 first)'; end if;
  select id into v_chap from public.chapter where subject_id=v_subj and lower(name)=lower(p_chapter) limit 1;
  if v_chap is null then raise exception 'Chapter % not found', p_chapter; end if;
  if exists (select 1 from public.question where chapter_id=v_chap and stem=p_stem) then return; end if;
  insert into public.question (subject_id, chapter_id, kind, difficulty, answer_type, stem, explanation)
  values (v_subj, v_chap, 'standard', p_difficulty, 'single', p_stem, p_explanation) returning id into v_qid;
  for i in 1..array_length(p_opts,1) loop
    insert into public.question_option (question_id, label, is_correct, position) values (v_qid, p_opts[i], i=p_correct, i-1);
  end loop;
end; $fn$;

select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$The banker's discount on a bill of ₹1,800 due 146 days hence at 10% per annum is:$q$, ARRAY[$q$₹72$q$,$q$₹90$q$,$q$₹180$q$,$q$₹65$q$], 1, $q$146 days = 146/365 = 0.4 yr. BD = F·R·T/100 = 1800·10·0.4/100 = ₹72.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$Find the banker's discount on a bill of ₹5,000 due 3 years hence at 5% per annum.$q$, ARRAY[$q$₹500$q$,$q$₹600$q$,$q$₹750$q$,$q$₹800$q$], 3, $q$BD = SI on face value = 5000·5·3/100 = ₹750.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$The banker's discount on a sum of ₹1,600 due 292 days hence at 15% per annum is:$q$, ARRAY[$q$₹150$q$,$q$₹192$q$,$q$₹210$q$,$q$₹175$q$], 2, $q$292/365 = 0.8 yr. BD = 1600·15·0.8/100 = ₹192.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$Find the banker's discount on ₹2,500 due 6 months hence at 8% per annum.$q$, ARRAY[$q$₹120$q$,$q$₹150$q$,$q$₹100$q$,$q$₹90$q$], 3, $q$T = 0.5 yr. BD = 2500·8·0.5/100 = ₹100.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$The banker's discount on a bill of ₹3,600 due 219 days hence at 12% per annum is:$q$, ARRAY[$q$₹240$q$,$q$₹300$q$,$q$₹259.20$q$,$q$₹216$q$], 3, $q$219/365 = 0.6 yr. BD = 3600·12·0.6/100 = ₹259.20.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$For a bill of ₹10,000 due 1 year hence at 8% per annum, which statement about the banker's discount (BD) and true discount (TD) is correct?$q$, ARRAY[$q$BD = TD$q$,$q$BD < TD$q$,$q$BD > TD$q$,$q$BD = 2·TD$q$], 3, $q$BD is SI on face value, TD is SI on present worth (< face value), so BD is always greater than TD.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$Find the banker's discount on ₹4,000 due 2 years hence at 6% per annum.$q$, ARRAY[$q$₹360$q$,$q$₹480$q$,$q$₹420$q$,$q$₹500$q$], 2, $q$BD = 4000·6·2/100 = ₹480.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$The banker's discount on a bill of ₹7,200 due 73 days hence at 10% per annum is:$q$, ARRAY[$q$₹144$q$,$q$₹150$q$,$q$₹160$q$,$q$₹120$q$], 1, $q$73/365 = 0.2 yr. BD = 7200·10·0.2/100 = ₹144.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$easy$q$, $q$The true discount and banker's discount on a certain sum are ₹100 and ₹110 respectively. What is the banker's gain?$q$, ARRAY[$q$₹210$q$,$q$₹105$q$,$q$₹10$q$,$q$₹100$q$], 3, $q$BG = BD − TD = 110 − 100 = ₹10.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$The banker's discount on a bill due 2 years hence at 10% per annum is ₹120. Find the true discount.$q$, ARRAY[$q$₹100$q$,$q$₹110$q$,$q$₹96$q$,$q$₹108$q$], 1, $q$TD = BD·100/(100+R·T) = 120·100/120 = ₹100.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$For a bill of ₹600 due 2 years hence at 10% per annum, find the banker's gain.$q$, ARRAY[$q$₹100$q$,$q$₹20$q$,$q$₹120$q$,$q$₹25$q$], 2, $q$BD = 600·10·2/100 = 120; TD = 600·20/120 = 100; BG = 120 − 100 = ₹20.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$The banker's discount on a sum due 1 year hence at 25% per annum is ₹250. Find the true discount.$q$, ARRAY[$q$₹180$q$,$q$₹200$q$,$q$₹210$q$,$q$₹225$q$], 2, $q$TD = BD·100/(100+R·T) = 250·100/125 = ₹200.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$A bill of ₹1,500 is due 2 years hence at 10% per annum. Find the banker's gain.$q$, ARRAY[$q$₹40$q$,$q$₹45$q$,$q$₹50$q$,$q$₹60$q$], 3, $q$BD = 1500·10·2/100 = 300; TD = 1500·20/120 = 250; BG = ₹50.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$The banker's discount and true discount on a sum are ₹195 and ₹150 respectively. Find the present worth.$q$, ARRAY[$q$₹450$q$,$q$₹500$q$,$q$₹550$q$,$q$₹600$q$], 2, $q$BG = 195 − 150 = 45; PW = TD²/BG = 150²/45 = 22500/45 = ₹500.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$The true discount on a bill due 2 years hence at 10% per annum is ₹100. Find the banker's discount.$q$, ARRAY[$q$₹110$q$,$q$₹120$q$,$q$₹125$q$,$q$₹130$q$], 2, $q$BD = TD(1 + R·T/100) = 100·(1 + 20/100) = ₹120.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$The true discount on a bill due 1 year hence at 25% per annum is ₹200. Find the present worth.$q$, ARRAY[$q$₹700$q$,$q$₹750$q$,$q$₹800$q$,$q$₹850$q$], 3, $q$PW = TD·100/(R·T) = 200·100/25 = ₹800.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$A bill of ₹700 is due 2 years hence at 6% per annum. Find the banker's gain.$q$, ARRAY[$q$₹9$q$,$q$₹12$q$,$q$₹15$q$,$q$₹18$q$], 1, $q$BD = 700·6·2/100 = 84; TD = 700·12/112 = 75; BG = 84 − 75 = ₹9.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$medium$q$, $q$The banker's discount on a bill due 8 months hence at 12% per annum is ₹108. Find the true discount.$q$, ARRAY[$q$₹96$q$,$q$₹100$q$,$q$₹104$q$,$q$₹120$q$], 2, $q$R·T = 12·(8/12) = 8. TD = BD·100/(100+8) = 108·100/108 = ₹100.$q$);
