select public._seed_arith_q($q$Banker's Discount$q$, $q$hard$q$, $q$The banker's gain on a bill is ₹24 and the true discount is ₹120. Find the banker's discount.$q$, ARRAY[$q$₹96$q$,$q$₹144$q$,$q$₹120$q$,$q$₹150$q$], 2, $q$BD = BG + TD = 24 + 120 = ₹144.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$hard$q$, $q$The banker's gain on a bill is ₹24 and the true discount is ₹120. Find the face value of the bill.$q$, ARRAY[$q$₹600$q$,$q$₹720$q$,$q$₹840$q$,$q$₹960$q$], 2, $q$BD = 144; F = BD·TD/(BD−TD) = 144·120/24 = ₹720.$q$);
select public._seed_arith_q($q$Banker's Discount$q$, $q$hard$q$, $q$The banker's gain on a certain sum due some time hence is ₹36 and the true discount is ₹60. Find the amount (face value) of the bill.$q$, ARRAY[$q$₹120$q$,$q$₹160$q$,$q$₹200$q$,$q$₹240$q$], 2, $q$BD = 36 + 60 = 96; F = BD·TD/BG = 96·60/36 = ₹160.$q$);
