select public._seed_arith_q($q$Banker's Discount$q$, $q$very_hard$q$, $q$The banker's discount and the true discount on a sum are ₹80 and ₹72 respectively. Find the sum due.$q$, ARRAY[$q$₹600$q$,$q$₹640$q$,$q$₹720$q$,$q$₹800$q$], 3, $q$BG = 80 − 72 = 8; sum = BD·TD/(BD−TD) = 80·72/8 = ₹720.$q$);
